    if(!(dateEl instanceof HTMLElement) || !(timeEl instanceof HTMLElement)) return;
    const now = new Date();
    dateEl.textContent = formatCustomDayNowDateLabel(now);
    timeEl.textContent = formatCustomDayNowTimeLabel(now);
