        scope: 'day_layout_render',
        view: String(calendar?.view?.type || ''),
        dayKey: selectedDayKey,
        blocked_total: totalBlocked,
        blocked_morning: morningRows.filter((row)=> row?.eventType === 'blocked_slot').length,
