  const resolveAgendaConsultorioLabelById = (consultorioId)=>{
    const safeId = sanitizeText(consultorioId || '');
    if(!safeId){
      return 'Consultorio';
    }
    const fromList = listAgendaConfigConsultorios().find((item)=> sanitizeText(item?.id || '') === safeId);
    const fromListLabel = sanitizeText(fromList?.label || '');
    if(fromListLabel && !isGenericConsultorioLabel(fromListLabel)){
      return fromListLabel;
    }
    const activeProfessional = (typeof window.mxmedResolveActiveProfessionalContext === 'function')
      ? window.mxmedResolveActiveProfessionalContext()
      : null;
    const fromContextList = (Array.isArray(activeProfessional?.consultorios) ? activeProfessional.consultorios : [])
      .find((item)=> sanitizeText(item?.id || item?.consultorio_id || '') === safeId);
    const fromContextName = sanitizeText(
      fromContextList?.name
      || fromContextList?.nombre
      || fromContextList?.consultorio_name
      || fromContextList?.title
      || fromContextList?.label
      || ''
    );
    if(fromContextName && !isGenericConsultorioLabel(fromContextName)){
      return fromContextName;
    }
    const contextDefaultName = (
      sanitizeText(activeProfessional?.default_consultorio_id || '') === safeId
      ? sanitizeText(activeProfessional?.default_consultorio_name || '')
      : ''
    );
    if(contextDefaultName && !isGenericConsultorioLabel(contextDefaultName)){
      return contextDefaultName;
    }
    const fromSelect = Array.from(els.consultorio?.options || [])
      .find((opt)=> sanitizeText(opt.value || '') === safeId);
    if(fromSelect && sanitizeText(fromSelect.textContent || '')){
      const optionLabel = sanitizeText(fromSelect.textContent || '');
      if(!isGenericConsultorioLabel(optionLabel)){
        return optionLabel;
      }
    }
    const fromProfilePane = resolveConsultorioLabelFromProfilePane(safeId);
    if(fromProfilePane){
      return fromProfilePane;
    }
    return `Consultorio ${safeId}`;
  };
  const applyConsultorioFallbackFromActiveContext = ()=>{
    if(!els.consultorio) return false;
    const activeProfessional = (typeof window.mxmedResolveActiveProfessionalContext === 'function')
      ? window.mxmedResolveActiveProfessionalContext()
      : null;
    const fallbackId = sanitizeText(
      activeProfessional?.default_consultorio_id
      || window.mxmedStore?.default_consultorio_id
      || window.mxmedStore?.defaultConsultorioId
      || ''
    );
    const fallbackName = sanitizeText(
      activeProfessional?.default_consultorio_name
      || window.mxmedStore?.facilityName
      || window.mxmedStore?.doctorProfile?.facility_name
      || ''
    );
    if(!fallbackName){
      return false;
    }
    const optionValue = fallbackId || CONSULTORIO_PROFILE_ONLY_VALUE;
    const optionLabel = fallbackName;
    const hasSameOption = Array.from(els.consultorio.options || []).some((opt)=>{
      return sanitizeText(opt.value) === optionValue && sanitizeText(opt.textContent || '') === optionLabel;
    });
    if(!hasSameOption){
      const optionHtml = `<option value="${optionValue.replace(/"/g, '&quot;')}">${optionLabel.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</option>`;
      els.consultorio.insertAdjacentHTML('beforeend', optionHtml);
    }
    if(!sanitizeText(els.consultorio.value || '') || sanitizeText(els.consultorio.value || '') === CONSULTORIO_UNAVAILABLE_VALUE){
      els.consultorio.value = optionValue;
    }
    syncCreateConsultorioOptions();
    if(els.consultorioModal && (!sanitizeText(els.consultorioModal.value || '') || sanitizeText(els.consultorioModal.value || '') === CONSULTORIO_UNAVAILABLE_VALUE)){
      els.consultorioModal.value = optionValue;
    }
    return true;
  };
  const applyLegacyAgendaConsultorioFallback = ()=>{
    if(!els.consultorio) return false;
    const doctorId = sanitizeText(getDoctorId() || '');
    if(doctorId !== AGENDA_LEGACY_DOCTOR_FALLBACK_ID) return false;
    const optionValue = '1';
    const optionLabel = 'Consultorio 1';
    const hasOption = Array.from(els.consultorio.options || []).some((opt)=> sanitizeText(opt.value) === optionValue);
    if(!hasOption){
      const optionHtml = `<option value="${optionValue}">${optionLabel}</option>`;
      els.consultorio.insertAdjacentHTML('beforeend', optionHtml);
    }
    const currentValue = sanitizeText(els.consultorio.value || '');
    if(!currentValue || currentValue === CONSULTORIO_UNAVAILABLE_VALUE || currentValue === CONSULTORIO_PROFILE_ONLY_VALUE){
      els.consultorio.value = optionValue;
    }
    syncCreateConsultorioOptions();
    if(els.consultorioModal){
      const modalValue = sanitizeText(els.consultorioModal.value || '');
      if(!modalValue || modalValue === CONSULTORIO_UNAVAILABLE_VALUE || modalValue === CONSULTORIO_PROFILE_ONLY_VALUE){
        els.consultorioModal.value = optionValue;
      }
    }
    return true;
  };

