    row.setAttribute('data-ne-rx-source', medication.source || 'manual');
    row.setAttribute('data-ne-rx-catalog-id', medication.catalog_id || '');
    row.setAttribute('data-ne-rx-memory-id', medication.doctor_memory_id || '');
