      els.certificadoSignatureInlinePrompt?.classList.add('d-none');
      setCertificadoNotice('');
      setCertificadoRemoteStatus('', 'muted');
      clearCertificadoSignaturePad();
      refreshCertificadoRegisteredSignature();
